import manifest from "@/content/images.json";

/**
 * Every image on the site comes from content/images.json, which is generated by
 * scripts/optimize-images.ts. The manifest carries intrinsic size, a blurred
 * placeholder and the dominant colour, so no layout shift is possible.
 */

export type ImageAsset = {
  name: string;
  src: string;
  width: number;
  height: number;
  aspect: number;
  blurDataURL: string;
  dominant: string;
  fit: "cover" | "contain";
  origin: "instagram" | "2gis-owner" | "2gis-visitor";
  note: string;
};

const assets = manifest.images as ImageAsset[];

const bySource = new Map(assets.map((asset) => [asset.src, asset]));

export function assetBySrc(src: string): ImageAsset {
  const asset = bySource.get(src);
  if (!asset) {
    throw new Error(
      `Изображение ${src} отсутствует в content/images.json. Запустите \`npm run images\`.`,
    );
  }
  return asset;
}

